type Nat = u32; // Assuming natural numbers are represented as u32

fn find_smallest(s: &Vec<Nat>) -> Option<Nat> {
    if s.is_empty() {
        return None;
    }
    
    // Use fold to find the smallest element
    s.iter().fold(None, |acc, &x| {
        match acc {
            None => Some(x),
            Some(current_min) => Some(if x < current_min { x } else { current_min }),
        }
    })
}

